      var lo=0, hi=r.length-1;
      while (hi-lo>1){ var m=(lo+hi)>>1; if (r[m].x<=x) lo=m; else hi=m; }
      var t=(x-r[lo].x)/((r[hi].x-r[lo].x)||1);
